mapper.select:
SELECT t.id, t.name, t.price, t.remark, t.sold, t.is_public, t.view_count, t.favorite_count, t.cover, t.created_at, t.updated_at, t.user_id, u.username, u.nickname
FROM tool t
LEFT JOIN user u ON t.user_id = u.id
WHERE t.deleted = 0

    AND t.user_id = #{dto.userId}


    AND t.name LIKE CONCAT('%', #{dto.name}, '%')


    AND t.price >= #{dto.minPrice}


    AND t.price <= #{dto.maxPrice}


    AND t.sold = #{dto.sold}


    AND t.is_public = #{dto.isPublic}

ORDER BY t.created_at DESC

mapper.update:
UPDATE tool
SET favorite_count = favorite_count + #{delta}
WHERE id = #{id}

UPDATE tool
SET view_count = view_count + 1
WHERE id = #{id}
